using System.Data.Common;

namespace YesSql.Provider
{
    /// <summary>
    /// Implemented by an <see cref="ISqlDialect"/> whose driver exposes the identifier generated by the last insert on a
    /// connection, so that it can be read without executing an additional statement after the insert.
    /// </summary>
    public interface ILastInsertIdDialect
    {
        /// <summary>
        /// Gets whether the identifier generated by the last insert can be read from a connection, which might not be
        /// one of the driver (e.g. a connection wrapped for profiling).
        /// </summary>
        bool CanReadLastInsertId(DbConnection connection);

        /// <summary>
        /// Returns the identifier generated by the last insert on a connection.
        /// </summary>
        long ReadLastInsertId(DbConnection connection);
    }
}
